    try:c.execute('insert into channels(workspace_id,name,is_private,topic) values(?,?,?,?)',(w['id'],name,int(bool(d.get('is_private'))),d.get('topic','')));cid=c.execute('select last_insert_rowid()').fetchone()[0];c.execute('insert into cmembers values(?,?)',(cid,u['id']));c.commit();r=dict(c.execute('select * from channels where id=?',(cid,)).fetchone());c.close();return self.sendj(201,{'channel':r})
    except sqlite3.IntegrityError:c.close();return err(self,409,'duplicate')
   m=re.match(r'/api/channels/(\d+)/join$',p)
   if m:
    ch=c.execute('select * from channels where id=?',(m.group(1),)).fetchone();w=c.execute('select * from workspaces where id=?',(ch['workspace_id'],)).fetchone() if ch else None
    if not ch:c.close();return err(self,404,'not found')
    c.execute('insert or ignore into members values(?,?,?)',(w['id'],u['id'],'member'));c.execute('insert or ignore into cmembers values(?,?)',(ch['id'],u['id']));c.commit();c.close();return self.sendj(200,{'channel':dict(ch)})
   m=re.match(r'/api/channels/(\d+)/messages$',p)
   if m:
    ch=int(m.group(1)); cr=c.execute('select * from channels where id=?',(ch,)).fetchone()
